        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(120.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(50.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(100.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(50.0f, tree.GetHeight(rootChild0), Tolerance);

        Assert.Equal(100.0f, tree.GetLeft(rootChild1), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild1), Tolerance);
        Assert.Equal(20.0f, tree.GetWidth(rootChild1), Tolerance);
        Assert.Equal(50.0f, tree.GetHeight(rootChild1), Tolerance);

        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Rtl);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(120.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(50.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(20.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(100.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(50.0f, tree.GetHeight(rootChild0), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild1), Tolerance);
