    [Fact]
    public void Min_max_percent_no_width_height() {
        using var tree = new LayoutTree();

        var root = tree.CreateNode();
        tree.SetPositionType(root, PositionType.Absolute);
        tree.SetDimension(root, Dimension.Width, StyleLength.Points(100.0f));
        tree.SetDimension(root, Dimension.Height, StyleLength.Points(100.0f));
        tree.SetAlignItems(root, Align.FlexStart);

        var rootChild0 = tree.CreateNode();
        tree.SetMinDimension(rootChild0, Dimension.Width, StyleLength.Percent(10.0f));
        tree.SetMaxDimension(rootChild0, Dimension.Width, StyleLength.Percent(10.0f));
        tree.SetMinDimension(rootChild0, Dimension.Height, StyleLength.Percent(10.0f));
        tree.SetMaxDimension(rootChild0, Dimension.Height, StyleLength.Percent(10.0f));
        tree.InsertChild(root, rootChild0, 0);
        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Ltr);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(100.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(100.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(10.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(10.0f, tree.GetHeight(rootChild0), Tolerance);

        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Rtl);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(100.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(100.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(90.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(10.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(10.0f, tree.GetHeight(rootChild0), Tolerance);
    }
